import { MeshStandardNodeMaterial, Group, Mesh, PlaneGeometry, DirectionalLight, AmbientLight } from 'three/webgpu';
import { color, vec2, uv, mix, smoothstep, uniform } from 'three/tsl';
import { gsap } from 'gsap';

export function createNode(config, ctx) {
  const { Group: ThreeGroup, Mesh: ThreeMesh, PlaneGeometry: ThreePlaneGeometry } = ctx.THREE;
  const group = new ThreeGroup();

  const colors = config.colors ?? config.intent?.visualSpec?.colors ?? {
    background: '#0b0b10',
    surface: '#14141a',
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    gradientStops: [{ at: 0, hex: '#1b1b23' }, { at: 1, hex: '#101015' }]
  };

  const navItems = [
    { text: 'HOME', route: 'hub-home' },
    { text: 'FEATURES', route: 'hub-features' },
    { text: 'COLLECTION', route: 'hub-collection' },
    { text: 'PRICING', route: 'hub-pricing' },
    { text: 'JOURNAL', route: 'hub-journal' }
  ];

  // 1. STAGE BACKDROP (Designed for dark, gradient backdrop to satisfy "STAGE, never void")
  const bgGeom = new ThreePlaneGeometry(12, 8);
  const bgMat = new MeshStandardNodeMaterial({
    roughness: 0.9,
    metalness: 0.1,
  });
  // Vertical albedo ramp
  const stop0 = colors.gradientStops[0]?.hex ?? '#1b1b23';
  const stop1 = colors.gradientStops[1]?.hex ?? '#101015';
  bgMat.colorNode = mix(color(stop1), color(stop0), uv().y);
  const bgMesh = new ThreeMesh(bgGeom, bgMat);
  bgMesh.position.z = -1.5;
  group.add(bgMesh);

  // LOCAL LIGHTS (Rim + Accent lights to craft visual depth)
  const localKey = new DirectionalLight('#ffffff', 1.2);
  localKey.position.set(2, 4, 3);
  group.add(localKey);

  const localRim = new DirectionalLight(colors.accent, 0.8);
  localRim.position.set(-2, -3, 1);
  group.add(localRim);

  const localFill = new AmbientLight('#ffffff', 0.2);
  group.add(localFill);

  // 2. CONTACT SHADOW PLANE
  const shadowGeom = new ThreePlaneGeometry(4.2, 0.9);
  const shadowMat = new MeshStandardNodeMaterial({
    color: '#000000',
    transparent: true,
    opacity: 0.35,
    roughness: 1.0,
  });
  shadowMat.colorNode = mix(color('#000000'), color('#000000'), uv().y);
  const shadowMesh = new ThreeMesh(shadowGeom, shadowMat);
  shadowMesh.position.set(0, -0.06, -0.05);
  group.add(shadowMesh);

  // 3. MACHINED RAIL
  const railGeom = new ThreePlaneGeometry(3.6, 0.5);
  const railMat = new MeshStandardNodeMaterial({
    roughness: 0.55,
    metalness: 0.5,
    clearcoat: 0.2,
  });
  // Smoothly vertical ramp on the rail itself
  railMat.colorNode = mix(color('#101015'), color('#1b1b23'), uv().y);
  const railMesh = new ThreeMesh(railGeom, railMat);
  railMesh.position.z = 0.15;
  group.add(railMesh);

  // 4. NAVIGATION ITEMS & INTERACTIVE REGIONS
  const itemWidth = 0.6;
  const paddingX = 0.68;
  const startX = -((navItems.length - 1) * paddingX) / 2;

  const textGroup = new Group();
  textGroup.position.z = 0.17; // Sit slightly forward from the rail
  group.add(textGroup);

  const textNodes = [];
  const hitBoxes = [];
  let activeIndex = 0;

  // Active Underline Bar
  const barGeom = new ThreePlaneGeometry(0.28, 0.025);
  const barMat = new MeshStandardNodeMaterial({
    color: colors.accent,
    emissive: colors.accent,
    emissiveIntensity: 1.8,
  });
  const barMesh = new ThreeMesh(barGeom, barMat);
  barMesh.position.set(startX, -0.16, 0.18);
  group.add(barMesh);

  // Create text entries and collision bounds
  navItems.forEach((item, index) => {
    const xPos = startX + index * paddingX;

    // Hit Cell mesh
    const hitGeom = new ThreePlaneGeometry(itemWidth, 0.34);
    const hitMat = new MeshStandardNodeMaterial({
      color: '#ffffff',
      transparent: true,
      opacity: 0.0,
      depthWrite: false,
    });
    const hitMesh = new ThreeMesh(hitGeom, hitMat);
    hitMesh.position.set(xPos, 0, 0.18);
    group.add(hitMesh);
    hitBoxes.push(hitMesh);

    // Text Instance using ctx.fontAtlas
    const isInitiallyActive = index === 0;
    const txt = ctx.fontAtlas.createText(item.text, {
      fontSize: 13,
      color: isInitiallyActive ? colors.paper : '#a6adba',
      align: 'center'
    });
    txt.position.set(xPos, -0.04, 0.01);
    textGroup.add(txt);
    textNodes.push(txt);

    // Pointer Events on the specific hit bounds
    hitMesh.userData.index = index;
    hitMesh.userData.item = item;
  });

  // Handler management
  const timelines = [];

  const handlePointerOver = (mesh) => {
    const idx = mesh.userData.index;
    if (idx === activeIndex) return;
    gsap.to(textNodes[idx].scale, { x: 1.05, y: 1.05, duration: 0.2 });
  };

  const handlePointerOut = (mesh) => {
    const idx = mesh.userData.index;
    if (idx === activeIndex) return;
    gsap.to(textNodes[idx].scale, { x: 1.0, y: 1.0, duration: 0.2 });
  };

  const handlePointerDown = (mesh) => {
    const idx = mesh.userData.index;
    // Press scale effect with depth dip depth-wise -0.03
    gsap.to(railMesh.scale, { x: 0.98, y: 0.98, duration: 0.12, ease: 'power2.out' });
    gsap.to(railMesh.position, { z: 0.12, duration: 0.12 });
  };

  const handlePointerUp = (mesh) => {
    const idx = mesh.userData.index;
    gsap.to(railMesh.scale, { x: 1.0, y: 1.0, duration: 0.4, ease: 'back.out(1.5)' });
    gsap.to(railMesh.position, { z: 0.15, duration: 0.4 });

    if (idx === activeIndex) return;

    // Transition of state
    const oldActive = activeIndex;
    activeIndex = idx;

    // Translate Underline Bar with weighted overshoot
    const targetX = startX + idx * paddingX;
    gsap.to(barMesh.position, {
      x: targetX,
      duration: 0.26,
      ease: 'back.out(1.04)'
    });

    // Animate color / scale of inactive list
    textNodes.forEach((node, i) => {
      const activeObj = node.children[0];
      if (activeObj?.material) {
        gsap.to(activeObj.material.color, {
          r: i === activeIndex ? 232/255 : 166/255,
          g: i === activeIndex ? 236/255 : 173/255,
          b: i === activeIndex ? 242/255 : 186/255,
          duration: 0.16
        });
      }
    });

    // Emit event mapping
    ctx.emit('navigate', { to: mesh.userData.item.route });
  };

  // Attach event routing on root userdata
  group.userData.handlers = {
    pointerover: (e) => {
      const hit = hitBoxes.find(h => h === e.intersection?.object);
      if (hit) handlePointerOver(hit);
    },
    pointerout: (e) => {
      const hit = hitBoxes.find(h => h === e.intersection?.object);
      if (hit) handlePointerOut(hit);
    },
    pointerdown: (e) => {
      const hit = hitBoxes.find(h => h === e.intersection?.object);
      if (hit) handlePointerDown(hit);
    },
    pointerup: (e) => {
      const hit = hitBoxes.find(h => h === e.intersection?.object);
      if (hit) handlePointerUp(hit);
    }
  };

  // Rise-in Entrance Animation
  group.position.y = -0.4;
  const entrance = gsap.to(group.position, {
    y: 0,
    duration: 0.7,
    ease: 'power3.out'
  });
  timelines.push(entrance);

  // Apply custom cinematic primitives if declared
  if (config.cinematicPrimitives) {
    config.cinematicPrimitives.forEach((prim) => {
      if (ctx.primitives[prim.name]) {
        const res = ctx.primitives[prim.name](group, prim.params);
        if (res && res.cleanup) {
          group.userData.customCleanup = res.cleanup;
        }
      }
    });
  }

  // Strict cleanup mandate
  group.userData.cleanup = () => {
    timelines.forEach(tl => tl.kill());
    if (group.userData.customCleanup) group.userData.customCleanup();
    bgGeom.dispose();
    bgMat.dispose();
    shadowGeom.dispose();
    shadowMat.dispose();
    railGeom.dispose();
    railMat.dispose();
    barGeom.dispose();
    barMat.dispose();
    hitBoxes.forEach((hb) => {
      hb.geometry.dispose();
      hb.material.dispose();
    });
  };

  return group;
}
